def compute(vars):
    commission = vars["v1"]
    ceiling = vars["v2"]

    if ceiling == 0:
        return None

    value = commission / ceiling * 100
    return {
        "value": value,
        "trace": {
            "commission": commission,
            "ceiling": ceiling,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
